-- ----------------------------
-- Table structure for Access
-- ----------------------------
DROP TABLE IF EXISTS `Access`;
CREATE TABLE `Access`  (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `debug` tinyint NOT NULL DEFAULT 0 COMMENT '是否为 DEBUG 调试数据，只允许在开发环境使用，测试和线上环境禁用：0-否，1-是。',
  `schema` varchar(100) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '数据库名/模式',
  `name` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL COMMENT '实际表名，例如 apijson_user',
  `alias` varchar(20) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '外部调用的表别名，例如 User，前端传参示例 { \"User\":{} }',
  `get` varchar(100) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL DEFAULT '[\"UNKNOWN\", \"LOGIN\", \"CONTACT\", \"CIRCLE\", \"OWNER\", \"ADMIN\"]' COMMENT '允许 get 的角色列表，例如 [\"LOGIN\", \"CONTACT\", \"CIRCLE\", \"OWNER\"]\n用 JSON 类型不能设置默认值，反正权限对应的需求是明确的，也不需要自动转 JSONArray。\nTODO: 直接 LOGIN,CONTACT,CIRCLE,OWNER 更简单，反正是开发内部用，不需要复杂查询。',
  `head` varchar(100) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL DEFAULT '[\"UNKNOWN\", \"LOGIN\", \"CONTACT\", \"CIRCLE\", \"OWNER\", \"ADMIN\"]' COMMENT '允许 head 的角色列表，例如 [\"LOGIN\", \"CONTACT\", \"CIRCLE\", \"OWNER\"]',
  `gets` varchar(100) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL DEFAULT '[\"LOGIN\", \"CONTACT\", \"CIRCLE\", \"OWNER\", \"ADMIN\"]' COMMENT '允许 gets 的角色列表，例如 [\"LOGIN\", \"CONTACT\", \"CIRCLE\", \"OWNER\"]',
  `heads` varchar(100) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL DEFAULT '[\"LOGIN\", \"CONTACT\", \"CIRCLE\", \"OWNER\", \"ADMIN\"]' COMMENT '允许 heads 的角色列表，例如 [\"LOGIN\", \"CONTACT\", \"CIRCLE\", \"OWNER\"]',
  `post` varchar(100) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL DEFAULT '[\"OWNER\", \"ADMIN\"]' COMMENT '允许 post 的角色列表，例如 [\"LOGIN\", \"CONTACT\", \"CIRCLE\", \"OWNER\"]',
  `put` varchar(100) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL DEFAULT '[\"OWNER\", \"ADMIN\"]' COMMENT '允许 put 的角色列表，例如 [\"LOGIN\", \"CONTACT\", \"CIRCLE\", \"OWNER\"]',
  `delete` varchar(100) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL DEFAULT '[\"OWNER\", \"ADMIN\"]' COMMENT '允许 delete 的角色列表，例如 [\"LOGIN\", \"CONTACT\", \"CIRCLE\", \"OWNER\"]',
  `date` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `detail` varchar(1000) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL,
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `alias_UNIQUE`(`alias` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 85 CHARACTER SET = utf8mb3 COLLATE = utf8mb3_general_ci COMMENT = '权限配置(必须)' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of Access
-- ----------------------------

-- ----------------------------
-- Table structure for Comment
-- ----------------------------
DROP TABLE IF EXISTS `Comment`;
CREATE TABLE `Comment`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '唯一标识',
  `toId` bigint NOT NULL DEFAULT 0 COMMENT '被回复的id',
  `userId` bigint NOT NULL COMMENT '评论人 User 的 id',
  `momentId` bigint NOT NULL COMMENT '动态id',
  `date` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建日期',
  `content` varchar(1000) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL COMMENT '内容',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `userId`(`userId` ASC) USING BTREE,
  INDEX `momentId`(`momentId` ASC) USING BTREE,
  INDEX `toId`(`toId` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1674906769686 CHARACTER SET = utf8mb3 COLLATE = utf8mb3_general_ci COMMENT = '评论' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of Comment
-- ----------------------------

-- ----------------------------
-- Table structure for Document
-- ----------------------------
DROP TABLE IF EXISTS `Document`;
CREATE TABLE `Document`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '唯一标识',
  `debug` tinyint NOT NULL DEFAULT 0 COMMENT '是否为 DEBUG 调试数据，只允许在开发环境使用，测试和线上环境禁用：0-否，1-是。',
  `userId` bigint NOT NULL COMMENT '管理员用户id。\n需要先建Admin表，新增登录等相关接口。',
  `testAccountId` bigint NOT NULL DEFAULT 0 COMMENT '测试账号id。0-不限',
  `version` tinyint NOT NULL DEFAULT 3 COMMENT '接口版本号\n<=0 - 不限制版本，任意版本都可用这个接口；\n>0 - 在这个版本添加的接口。\n\n可在给新版文档前调高默认值，新增的测试用例就不用手动设置版本号了。',
  `name` varchar(100) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL COMMENT '接口名称',
  `type` varchar(5) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL DEFAULT 'JSON' COMMENT 'PARAM - GET  url parameters,\nFORM - POST  application/www-x-form-url-encoded,\nJSON - POST  application/json',
  `url` varchar(250) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL COMMENT '请求地址',
  `request` text CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL COMMENT '请求\n用json格式会导致强制排序，而请求中引用赋值只能引用上面的字段，必须有序。',
  `apijson` text CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL COMMENT '从 request 映射为实际的 APIJSON 请求 JSON',
  `sqlauto` text CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL COMMENT '为 SQLAuto 留的字段，格式为\\\\\\\\n{“sql”:”SELECT * FROM `sys`.`Comment` LIMIT ${limit}”,”arg”:”limit: 3”}',
  `standard` text CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL,
  `header` text CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL COMMENT '请求头 Request Header：\nkey: value  //注释',
  `date` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建日期',
  `detail` text CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL COMMENT '详细的说明，可以是普通文本或 Markdown 格式文本',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1673597032762 CHARACTER SET = utf8mb3 COLLATE = utf8mb3_general_ci COMMENT = '测试用例文档\n后端开发者在测试好后，把选好的测试用例上传，这样就能共享给前端/客户端开发者' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of Document
-- ----------------------------

-- ----------------------------
-- Table structure for Function
-- ----------------------------
DROP TABLE IF EXISTS `Function`;
CREATE TABLE `Function`  (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `debug` tinyint NOT NULL DEFAULT 0 COMMENT '是否为 DEBUG 调试数据，只允许在开发环境使用，测试和线上环境禁用：0-否，1-是。',
  `userId` bigint NOT NULL COMMENT '管理员用户Id',
  `language` varchar(45) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '语言：Java(java), JavaScript(js), Lua(lua), Python(py), Ruby(ruby), PHP(php) 等，NULL 默认为 Java，JDK 1.6-11 默认支持 JavaScript，JDK 12+ 需要额外依赖 Nashron/Rhiro 等 js 引擎库，其它的语言需要依赖对应的引擎库，并在 ScriptEngineManager 中注册',
  `name` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL COMMENT '方法名',
  `returnType` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT 'Object' COMMENT '返回值类型。TODO RemoteFunction 校验 type 和 back',
  `arguments` varchar(100) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '参数列表，每个参数的类型都是 String。\n用 , 分割的字符串 比 [JSONArray] 更好，例如 array,item ，更直观，还方便拼接函数。',
  `demo` json NOT NULL COMMENT '可用的示例。\nTODO 改成 call，和返回值示例 back 对应。',
  `detail` varchar(1000) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL COMMENT '详细描述',
  `version` tinyint NOT NULL DEFAULT 0 COMMENT '允许的最低版本号，只限于GET,HEAD外的操作方法。\nTODO 使用 requestIdList 替代 version,tag,methods',
  `tag` varchar(20) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '允许的标签.\nnull - 允许全部\nTODO 使用 requestIdList 替代 version,tag,methods',
  `methods` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '允许的操作方法。\nnull - 允许全部\nTODO 使用 requestIdList 替代 version,tag,methods',
  `date` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `return` varchar(45) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '返回值示例',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 30 CHARACTER SET = utf8mb3 COLLATE = utf8mb3_general_ci COMMENT = '远程函数。强制在启动时校验所有demo是否能正常运行通过' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of Function
-- ----------------------------

-- ----------------------------
-- Table structure for Login
-- ----------------------------
DROP TABLE IF EXISTS `Login`;
CREATE TABLE `Login`  (
  `id` bigint NOT NULL COMMENT '唯一标识',
  `userId` bigint NOT NULL COMMENT '用户id',
  `type` tinyint NOT NULL COMMENT '类型\n0-密码登录\n1-验证码登录',
  `date` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建日期',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb3 COLLATE = utf8mb3_general_ci COMMENT = '@deprecated，登录信息存session' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of Login
-- ----------------------------

-- ----------------------------
-- Table structure for Method
-- ----------------------------
DROP TABLE IF EXISTS `Method`;
CREATE TABLE `Method`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '唯一主键',
  `userId` bigint NOT NULL COMMENT '管理员用户Id',
  `package` varchar(500) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '包名',
  `class` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '类名，注意内部类需要写成 外部类名$内部类名，例如 SharedPreferences$Editor',
  `constructor` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '构造方法名，一般不传，默认为类名；传的话主要是用在单例模式类的 getInstance 等方法',
  `classArgs` text CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL COMMENT '[\n        {   //User user\n            \"type\": \"apijson.demo.server.model.User\",\n            \"value\": {\n                \"id\": 1,\n                \"name\": \"APIJSON\"\n            }\n        },\n        {   //String id，不填 type 的话会根据 value 自动确定\n            \"value\": \"id\"\n        }\n]',
  `genericClassArgs` text CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL COMMENT '带泛型的构造方法参数名，例如\n[\n        {   //List<User> list\n            \"type\": “java.util.List<T>”,\n            \"value\": [{\n                \"id\": 1,\n                \"name\": \"APIJSON\"\n            }]\n        },\n        {   //String id，不填 type 的话会根据 value 自动确定\n            \"value\": \"id\"\n        }\n]',
  `method` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL COMMENT '方法名',
  `methodArgs` text CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL COMMENT '参数列表，格式是\n[\n        {   //User user\n            \"type\": \"apijson.demo.server.model.User\",\n            \"value\": {\n                \"id\": 1,\n                \"name\": \"APIJSON\"\n            }\n        },\n        {   //String id，不填 type 的话会根据 value 自动确定\n            \"value\": \"id\"\n        }\n]',
  `genericMethodArgs` text CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL COMMENT '带泛型的方法参数名，例如\n[\n        {   //List<User> list\n            \"type\": “java.util.List<T>”,\n            \"value\": [{\n                \"id\": 1,\n                \"name\": \"APIJSON\"\n            }]\n        },\n        {   //String id，不填 type 的话会根据 value 自动确定\n            \"value\": \"id\"\n        }\n]',
  `exceptions` varchar(500) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '异常类型列表',
  `genericExceptions` varchar(500) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '带泛型的异常类型列表',
  `type` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '返回值类型。TODO RemoteMethod 校验 type 和 back',
  `genericType` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '带泛型的返回值类型',
  `static` tinyint NOT NULL DEFAULT 0 COMMENT '是否为 static 方法： 0-false; 1-true',
  `ui` tinyint NOT NULL DEFAULT 0 COMMENT '0-非 UI 方法，1 - UI 方法',
  `request` text CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL COMMENT '完整请求',
  `demo` json NULL COMMENT '可用的示例。\nTODO 改成 call，和返回值示例 back 对应。',
  `detail` varchar(1000) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL COMMENT '详细描述',
  `date` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1671611391580 CHARACTER SET = utf8mb3 COLLATE = utf8mb3_general_ci COMMENT = '要做单元测试的方法(如果用到单元测试，则必须)' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of Method
-- ----------------------------

