  `pictureList` json NOT NULL COMMENT '图片列表',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `userId`(`userId` ASC, `date` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1706510426943 CHARACTER SET = utf8mb3 COLLATE = utf8mb3_general_ci COMMENT = '动态' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of Moment
-- ----------------------------

-- ----------------------------
-- Table structure for Praise
-- ----------------------------
DROP TABLE IF EXISTS `Praise`;
CREATE TABLE `Praise`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '动态id',
  `momentId` bigint NOT NULL COMMENT '唯一标识',
  `userId` bigint NOT NULL COMMENT '用户id',
  `date` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT '点赞时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 20 CHARACTER SET = utf8mb3 COLLATE = utf8mb3_general_ci COMMENT = '如果对Moment写安全要求高，可以将Moment内praiserUserIdList分离到Praise表中，作为userIdList。\n权限注解也改下：\n@MethodAccess(\n		PUT = {OWNER, ADMIN}\n		)\nclass Moment {\n       …\n}\n\n@MethodAccess(\n		PUT = {LOGIN, CONTACT, CIRCLE, OWNER, ADMIN}\n		)\n class Praise {\n       …\n }\n' ROW_FORMAT = DYNAMIC;

