  `name` varchar(100) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL COMMENT '名称',
  `config` varchar(5000) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL COMMENT '配置',
  `date` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1671271730042 CHARACTER SET = utf8mb3 COLLATE = utf8mb3_general_ci COMMENT = '随机测试配置(必须)' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of Random
-- ----------------------------

-- ----------------------------
-- Table structure for Request
-- ----------------------------
DROP TABLE IF EXISTS `Request`;
CREATE TABLE `Request`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '唯一标识',
  `debug` tinyint NOT NULL DEFAULT 0 COMMENT '是否为 DEBUG 调试数据，只允许在开发环境使用，测试和线上环境禁用：0-否，1-是。',
  `version` tinyint NOT NULL DEFAULT 1 COMMENT 'GET,HEAD可用任意结构访问任意开放内容，不需要这个字段。\n其它的操作因为写入了结构和内容，所以都需要，按照不同的version选择对应的structure。\n\n自动化版本管理：\nRequest JSON最外层可以传  “version”:Integer 。\n1.未传或 <= 0，用最新版。 “@order”:”version-“\n2.已传且 > 0，用version以上的可用版本的最低版本。 “@order”:”version+”, “version{}”:”>={version}”',
  `method` varchar(10) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT 'GETS' COMMENT '只限于GET,HEAD外的操作方法。',
  `tag` varchar(30) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL COMMENT '标签',
  `structure` json NOT NULL COMMENT '结构。\nTODO 里面的 PUT 改为 UPDATE，避免和请求 PUT 搞混。',
  `detail` varchar(10000) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '详细说明',
  `date` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建日期',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1658229984442 CHARACTER SET = utf8mb3 COLLATE = utf8mb3_general_ci COMMENT = '请求参数校验配置(必须)。\n最好编辑完后删除主键，这样就是只读状态，不能随意更改。需要更改就重新加上主键。\n\n每次启动服务器时加载整个表到内存。\n这个表不可省略，model内注解的权限只是客户端能用的，其它可以保证即便服务端代码错误时也不会误删数据。' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of Request
-- ----------------------------

-- ----------------------------
-- Table structure for Script
-- ----------------------------
DROP TABLE IF EXISTS `Script`;
CREATE TABLE `Script`  (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `userId` bigint NOT NULL DEFAULT 0 COMMENT '用户 id',
  `testAccountId` bigint NOT NULL DEFAULT 0 COMMENT '测试账号 id',
  `documentId` bigint NOT NULL DEFAULT 0 COMMENT '测试用例 id',
  `simple` tinyint NOT NULL DEFAULT 0 COMMENT '是否为可直接执行的简单代码段：0-否 1-是',
  `ahead` tinyint NOT NULL DEFAULT 0 COMMENT '是否为前置脚本',
  `title` varchar(100) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '函数名',
  `name` varchar(100) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL COMMENT '名称',
  `script` text CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL,
  `date` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `detail` varchar(1000) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL,
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `id_UNIQUE`(`id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1671083305190 CHARACTER SET = utf8mb3 COLLATE = utf8mb3_general_ci COMMENT = '脚本，前置预处理脚本、后置断言和恢复脚本等' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of Script
-- ----------------------------

-- ----------------------------
-- Table structure for TestRecord
-- ----------------------------
DROP TABLE IF EXISTS `TestRecord`;
CREATE TABLE `TestRecord`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '唯一标识',
  `headless` tinyint NOT NULL DEFAULT 0 COMMENT '是否是用于 CI/CD 的无头执行结果，而不是通过 APIAuto 等前端网页 UI 来执行',
  `userId` bigint NOT NULL COMMENT '用户id',
  `testAccountId` bigint NOT NULL DEFAULT 0,
  `documentId` bigint NOT NULL COMMENT '测试用例文档id',
  `randomId` bigint NOT NULL DEFAULT 0 COMMENT '随机配置 id',
  `host` varchar(1000) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL,
  `date` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建日期',
  `duration` bigint NULL DEFAULT NULL COMMENT '服务处理耗时，单位为毫秒(ms)',
  `minDuration` bigint NULL DEFAULT NULL COMMENT '统计过的最短服务处理耗时，单位为毫秒(ms)',
  `maxDuration` bigint NULL DEFAULT NULL COMMENT '统计过的最长服务处理耗时，单位为毫秒(ms)',
  `response` text CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL COMMENT '接口返回结果JSON',
  `compare` text CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL COMMENT '对比结果',
  `standard` text CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL COMMENT 'response 的校验标准，是一个 JSON 格式的 AST ，描述了正确 Response 的结构、里面的字段名称、类型、长度、取值范围 等属性。',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1673941833884 CHARACTER SET = utf8mb3 COLLATE = utf8mb3_general_ci COMMENT = '测试记录(必须)\n主要用于保存自动化接口回归测试。5.0.0 可能改为 Test(先废弃 Test 表) ' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of TestRecord
-- ----------------------------

-- ----------------------------
-- Table structure for Verify
-- ----------------------------
DROP TABLE IF EXISTS `Verify`;
CREATE TABLE `Verify`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '唯一标识',
  `type` int NOT NULL DEFAULT 0 COMMENT '类型：\n0-登录\n1-注册\n2-修改登录密码\n3-修改支付密码',
  `phone` bigint NOT NULL COMMENT '手机号',
  `verify` int NOT NULL COMMENT '验证码',
  `date` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1705990255273 CHARACTER SET = utf8mb3 COLLATE = utf8mb3_general_ci COMMENT = '登录信息表，存储用户名、登录类型、验证码等。' ROW_FORMAT = DYNAMIC;

