-- ----------------------------
-- Table structure for apijson_privacy
-- ----------------------------
DROP TABLE IF EXISTS `apijson_privacy`;
CREATE TABLE `apijson_privacy`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '唯一标识',
  `certified` tinyint NOT NULL DEFAULT 0 COMMENT '已认证',
  `phone` bigint NOT NULL COMMENT '手机号，仅支持 11 位数的。不支持 +86 这种国家地区开头的。如果要支持就改为 VARCHAR(14)',
  `balance` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '余额',
  `_password` varchar(20) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL COMMENT '登录密码',
  `_payPassword` int NOT NULL DEFAULT 123456 COMMENT '支付密码',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `phone_UNIQUE`(`phone` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1705982267984 CHARACTER SET = utf8mb3 COLLATE = utf8mb3_general_ci COMMENT = '用户隐私信息表。\n对安全要求高，不想泄漏真实名称。对外名称为 Privacy' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of apijson_privacy
-- ----------------------------

-- ----------------------------
-- Table structure for apijson_user
-- ----------------------------
DROP TABLE IF EXISTS `apijson_user`;
CREATE TABLE `apijson_user`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '唯一标识',
  `sex` tinyint NOT NULL DEFAULT 0 COMMENT '性别：\n0-男\n1-女',
  `name` varchar(20) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL COMMENT '名称',
  `tag` varchar(45) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '标签',
  `head` varchar(300) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT 'https://raw.githubusercontent.com/TommyLemon/StaticResources/master/APIJSON_Logo.png' COMMENT '头像url',
  `contactIdList` json NULL COMMENT '联系人id列表',
  `pictureList` json NULL COMMENT '照片列表',
  `date` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建日期',
  PRIMARY KEY (`id`) USING BTREE,
  FULLTEXT INDEX `name_tag_index`(`name`, `tag`) WITH PARSER `ngram`
) ENGINE = InnoDB AUTO_INCREMENT = 1705982267984 CHARACTER SET = utf8mb3 COLLATE = utf8mb3_general_ci COMMENT = '用户公开信息表。\n对安全要求高，不想泄漏真实名称。对外名称为 User' ROW_FORMAT = DYNAMIC;

