INSERT INTO `Document` VALUES (1559995734352, 0, 82001, 0, 3, 'get 自定义关键词和远程函数的应用', 'JSON', '/get', '{\n    \"User\": {\n        \"id\": 82001,\n        \"@column\": \"contactIdList\",\n        \"@value\": 82006,\n        \"isPraise()\": \"isContain(contactIdList,@value)\"\n    }\n}', NULL, NULL, '{\n    \"notnull\": true,\n    \"type\": \"object\",\n    \"valueLevel\": 0,\n    \"values\": [\n        {\n            \"User\": {\n                \"notnull\": true,\n                \"type\": \"object\",\n                \"valueLevel\": 0,\n                \"values\": [\n                    {\n                        \"id\": {\n                            \"notnull\": true,\n                            \"type\": \"integer\",\n                            \"valueLevel\": 1,\n                            \"values\": [\n                                82001\n                            ],\n                            \"lengthLevel\": 1,\n                            \"lengths\": [\n                                5\n                            ],\n                            \"trend\": {\n                                \"top\": 4\n                            },\n                            \"comment\": \"主键\"\n                        },\n                        \"@column\": {\n                            \"notnull\": true,\n                            \"type\": \"string\",\n                            \"valueLevel\": 3,\n                            \"values\": [],\n                            \"lengthLevel\": 1,\n                            \"lengths\": [\n                                13\n                            ]\n                        },\n                        \"@value\": {\n                            \"notnull\": true,\n                            \"type\": \"integer\",\n                            \"valueLevel\": 1,\n                            \"values\": [\n                                82006\n                            ],\n                            \"