INSERT INTO `Document` VALUES (1607881932306, 0, 99999, 0, 3, '@raw 自定义 SQL 片段', 'JSON', '/get', '{   // 类似 12306 根据始发站和到达站来过滤火车班次，班次和线路多对一，线路和站点多对多\n    \"sql@\": {\n        \"from\": \"Comment\",\n        \"join\": \"&/Comment:to/userId@\",\n        \"Comment\": {  // 假装是始发站\n            \"@column\": \"userId\",\n            \"content~\": \"a\",  // 假装是站点名\n            \"momentId>\": \"to.momentId\",\n            \"@raw\": \"momentId>\"\n        },\n        \"Comment:to\": {  // 假装是终点站\n            \"userId@\": \"/Comment/userId\",\n            \"@column\": \"\",\n            \"content~\": \"j\"  // 假装是站点名\n        }\n    },\n    \"[]\": {\n        \"Moment\": {  // 假装是班次\n            \"userId{}@\": {\n                \"from\": \"User\",\n                \"User\": {  // 假装是线路\n                    \"id{}@\": \"sql\",\n                    \"@column\": \"id\"\n                }\n            }\n        }\n    },\n    \"@explain\": true\n}\n                                                                                                                                                                                                              \n', NULL, NULL, NULL, '', '2020-12-14 09:52:12', NULL);
