INSERT INTO `Document` VALUES (1651807254036, 0, 88888, 0, 3, '查询 用户名、用户标签 或 评论内容 包含关键词的 用户+评论列表 的列表', 'JSON', '/get', '{\n    \"[]\": {\n        \"join\": \"/Comment\",\n        \"User\": {\n            \"name~\": \"an\",\n            \"tag~\": \"an\",\n            \"@combine\": \"name~,tag~\",\n            \"@column\": \"id,name,tag\",\n            \"@group\": \"id\"\n        },\n        \"Comment\": {\n            \"userId@\": \"/User/id\",\n            \"content~\": \"an\",\n            \"@column\": \"id,userId,content\"\n        },\n        \"Comment[]\": {\n            \"Comment\": {\n                \"userId@\": \"[]/User/id\"\n            }\n        }\n    },\n    \"@explain\": true\n}', NULL, NULL, '{\n    \"notnull\": true,\n    \"type\": \"object\",\n    \"valueLevel\": 0,\n    \"values\": [\n        {\n            \"[]\": {\n                \"notnull\": true,\n                \"type\": \"object\",\n                \"valueLevel\": 0,\n                \"values\": [\n                    {\n                        \"join\": {\n                            \"notnull\": true,\n                            \"type\": \"string\",\n                            \"valueLevel\": 3,\n                            \"values\": [],\n                            \"lengthLevel\": 1,\n                            \"lengths\": [\n                                8\n                            ]\n                        },\n                        \"User\": {\n                            \"notnull\": true,\n                            \"type\": \"object\",\n                            \"valueLevel\": 0,\n                            \"values\": [\n                                {\n                                    \"name~\": {\n                                        \"notnull\": true,\n                                        \"type\": \"string\",\n                                        \"valueLevel\": 3,\n                                        \"values\": [],\n                  