INSERT INTO `Document` VALUES (1662568938435, 0, 82003, 0, 3, '默认测试用例', 'JSON', '/sys', '{}', NULL, 'SELECT  `Comment`.`userId`, `User`.`id`, COUNT(1)\nFROM `sys`.`Comment` AS `Comment`\nINNER JOIN `sys`.`apijson_user` AS `User`\n  ON `User`.`id` = `Comment`.`userId`\n    AND `User`.`name` LIKE ${searchKey}\nGROUP BY `User`.`id` HAVING ((`User`.`id`) % ${userId} != 0)\nORDER BY `User`.`id` ASC LIMIT ${limit} OFFSET ${offset}', NULL, 'searchKey: \'%a%\'\nuserId: 82001\nlimit: 3\noffset: 0', '2022-09-08 08:42:18', NULL);
INSERT INTO `Document` VALUES (1662569033547, 0, 82003, 0, 3, '带变量查询 LIKE, LIMIT', 'JSON', '/sys', '{}', NULL, 'SELECT * FROM sys.Comment  \nWHERE content LIKE concat(\'%\',${key},\'%\')\nLIMIT ${limit}', NULL, 'key: \"s\"\nlimit: 2', '2022-09-08 08:43:53', NULL);
INSERT INTO `Document` VALUES (1662569350286, 0, 82003, 0, 3, '简单查询', 'JSON', '/sys', '{}', NULL, 'SELECT * FROM sys.Comment ORDER BY id DESC LIMIT 3', NULL, '', '2022-09-08 08:49:10', NULL);
INSERT INTO `Document` VALUES (1662603529187, 0, 82003, 0, 3, '两表 JOIN & 多字段搜索', 'JSON', '/sys', '{}', NULL, 'SELECT `User`.`id`,`User`.`name`,`User`.`tag`, `Comment`.* \nFROM `sys`.`apijson_user` AS `User` \nINNER JOIN `sys`.`Comment` AS `Comment` ON `Comment`.`userId`=`User`.`id` \nWHERE ( ( (`User`.`name` REGEXP BINARY ${searchKey1}) \n  OR (`User`.`tag` REGEXP BINARY ${searchKey2}) ) \n  OR ( ( (`Comment`.`content` REGEXP BINARY ${searchKey3}) ) ) ) \nGROUP BY `User`.`id` LIMIT ${offset}, ${limit} \n', NULL, 'searchKey1: \'an\'\nsearchKey2: \'an\'\nsearchKey3: \'an\'\noffset: 0\nlimit: 3', '2022-09-08 18:18:49', NULL);
INSERT INTO `Document` VALUES (1662603872425, 0, 82003, 0, 3, '单表 HAVING OR', 'JSON', '/sys', '{}', NULL, 'SELECT `toId`,avg(`id`) AS `avgId` \nFROM `sys`.`Comment` \nGROUP BY `toId` \nHAVING `toId`>${minToId} OR `avgId`<=${maxAvgId} \nLIMIT 10', NULL, 'minToId: 0\nmaxAvgId: 10000', '2022-09-08 18:24:32', NULL);
INSERT INTO `Document` VALUES (1662604351793, 0, 82003, 0, 3, '全文检索 match AGAINST', 'JSON', '/sys', '{}', NULL, 'SELECT `name`,`tag`,match(`name`,`tag`) AGAINST (${key1} IN NATURAL LANGUAGE MODE) AS `match` \nFROM `sys`.`apijson_user` \nWHERE ( (match(`name`,`tag`) AGAINST (${key2} IN NATURAL LANGUAGE MODE)>=1) ) \nHAVING ( match(`name`,`tag`) AGAINST (${key3} IN NATURAL LANGUAGE MODE)<5 ) \nLIMIT 10', NULL, 'key1: \'tom*\'\nkey2: \'tom*\'\nkey3: \'tom*\'', '2022-09-08 18:32:31', NULL);
INSERT INTO `Document` VALUES (1662604680510, 0, 82003, 0, 3, 'JOIN ON 字段、条件、分组、聚合、排序等', 'JSON', '/sys', '{}', NULL, 'SELECT `Comment`.`userId`, `User`.`id`,count(1) \nFROM `sys`.`Comment` AS `Comment` \nINNER JOIN `sys`.`apijson_user` AS `User` \n  ON `User`.`id` = `Comment`.`userId` \n    AND ( ( (`User`.`name` LIKE ${like}) OR (`User`.`tag` REGEXP ${regexp}) ) ) \nGROUP BY `User`.`id` HAVING ( (`User`.`id`)%7!=0 ) \nORDER BY `User`.`id` ASC LIMIT 3', NULL, 'like: \'%a%\'\nregexp: \'a\'', '2022-09-08 18:38:00', NULL);
INSERT INTO `Document` VALUES (1662605088494, 0, 82003, 0, 3, '窗口函数 sum(..)OVER(PARTITION BY.. ODER BY..)', 'JSON', '/sys', '{}', NULL, 'SELECT sum(`id`) OVER (PARTITION BY `toId` ORDER BY `date` DESC) \nFROM `sys`.`Comment` LIMIT ${limit} OFFSET ${offset}', NULL, 'limit: 3\noffset: 0', '2022-09-08 18:44:48', NULL);
INSERT INTO `Document` VALUES (1662605495868, 0, 82003, 0, 3, 'Moment INNER JOIN LEFT JOIN Comment WHERE AND', 'JSON', '/sys', '{}', NULL, 'SELECT `Moment`.`id`,`Moment`.`userId`,`Moment`.`content`, `User`.`id`,`User`.`name`, `Comment`.* \nFROM `sys`.`Moment` AS `Moment` \nINNER JOIN `sys`.`apijson_user` AS `User` ON `User`.`id` = `Moment`.`userId` \nLEFT JOIN ( SELECT * FROM `sys`.`Comment` ) AS `Comment` ON `Comment`.`momentId` = `Moment`.`id` \nWHERE ( ( (`Moment`.`content` REGEXP ${regexp}) ) AND ( ( (`User`.`sex` = ${sex}) ) ) ) \nLIMIT 10', NULL, 'regexp: \'a\'\nsex: 0', '2022-09-08 18:51:35', NULL);
INSERT INTO `Document` VALUES (1662606200791, 0, 82003, 0, 3, 'INSERT INTO sys.Comment', 'JSON', '/sys', '{}', NULL, 'INSERT INTO `sys`.`Comment`(`momentId`,`userId`,`content`) \nVALUES(${momentId}, ${userId}, ${content})', NULL, 'momentId: 15\nuserId: 82001\ncontent: \"test\"', '2022-09-08 19:03:20', NULL);
INSERT INTO `Document` VALUES (1662606482664, 0, 82003, 0, 3, 'UPDATE User SET name WHERE id', 'JSON', '/sys', '{}', NULL, 'UPDATE `sys`.`apijson_user` \nSET `name` = ${name}\nWHERE ( (`id` = ${id}) ) LIMIT 1', NULL, 'name: \'Test User\'\nid: 82001', '2022-09-08 19:08:02', NULL);
INSERT INTO `Document` VALUES (1662606992370, 0, 82003, 0, 3, 'WHERE id>${minId} AND id<=${maxId}', 'JSON', '/sys', '{}', NULL, 'SELECT count(*) AS count FROM `sys`.`apijson_user` \nWHERE ( (`id` > ${minId} AND `id` <= ${maxId}) ) ', NULL, 'minId: 82001\nmaxId: 820010', '2022-09-08 19:16:32', NULL);
