INSERT INTO `Script` VALUES (1, 0, 0, 0, 0, 0, NULL, 'getType', 'function getType(curObj, key) {\n    var val = curObj == null ? null : curObj[key];\n    return val instanceof Array ? \"array\" : typeof val;\n}', '2022-11-17 08:01:23', NULL);
INSERT INTO `Script` VALUES (2, 0, 0, 0, 0, 0, NULL, 'isContain', 'function isContain(curObj, arrKey, valKey) {\n    var arr = curObj == null ? null : curObj[arrKey];\n    var val = curObj == null ? null : curObj[valKey];\n    return arr != null && arr.indexOf(val) >=0;\n}', '2022-11-17 08:02:48', NULL);
INSERT INTO `Script` VALUES (3, 0, 0, 0, 1, 0, NULL, 'init', 'var i = 1;\n\"init done \"  + i;', '2022-11-17 08:41:35', NULL);
INSERT INTO `Script` VALUES (4, 0, 0, 0, 0, 0, NULL, 'length', 'function length(curObj, key) {\n    var val = curObj == null ? null : curObj[key];\n    return val == null ? 0 : val.length;\n}', '2022-11-17 09:18:43', NULL);
