INSERT INTO `Script` VALUES (1670877914051, 82001, 0, 0, 1, 1, '执行脚本 2022-12-13 04:44', '', 'function assert(assertion, msg) {\n     if (assertion === true) {\n         return\n     }\n     if (msg == null) {\n         msg = \'assert failed! assertion = \' + assertion\n     }\n\n     if (isTest) {\n         console.log(msg)\n         alert(msg)\n     } else {\n         throw new Error(msg)\n     } \n}  \n\nif (isTest) {\n     assert(true)\n     assert(false)\n     assert(true, \'ok\')\n     assert(false, \'data.User shoule not be null!\') \n}\n\nfunction getCurAccount() {\n  return App.getCurrentAccount()\n}', '2022-12-13 12:45:14', NULL);
INSERT INTO `Script` VALUES (1670878495619, 82001, 82002, 0, 1, 0, '执行脚本 2022-12-13 04:54', '', 'function getCurAccount() {\n  return App.getCurrentAccount()\n}', '2022-12-13 12:54:55', NULL);
INSERT INTO `Script` VALUES (1670878529042, 82001, 82001, 0, 1, 1, '执行脚本 2022-12-13 04:55', '', 'function getCurAccount() {\n  return App.getCurrentAccount()\n}', '2022-12-13 12:55:29', NULL);
